values.value:
{
  "fields": [
    {
      "apiName": "mast_standard_pole",
      "label": "Type of Pole - Standard",
      "type": "picklist",
      "required": true,
      "options": [
        "Standard Lighting Pole",
        "Custom Lighting Pole",
        "Mid Hinge Pole"
      ],
      "controllingField": "type_of_mast",
      "controllingValues": [
        "Octagonal Pole"
      ]
    },
    {
