            {
              "id": "op_general_details",
              "label": "General Details - Segments",
              "expanded": true,
              "fields": [
                {
                  "apiName": "s1_no_of_items",
                  "label": "No. of Items (Segment 1)",
                  "type": "number",
                  "colSpan": 4,
                  "defaultValue": 1,
                  "max": 10
                },
